def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape

    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def outline(pts):
        # shortest closed tour through all marker points (keeps concave corners)
        pts = sorted(set(pts))
        n = len(pts)
        if n < 3:
            return pts
        dist = [[((a[0]-b[0])**2+(a[1]-b[1])**2)**0.5 for b in pts] for a in pts]
        dp = {(1, 0): (0.0, (0,))}
        for mask in range(1, 1 << n):
            if not mask & 1:
                continue
            for last in range(n):
                if (mask, last) not in dp:
                    continue
                length, path = dp[(mask, last)]
                for nxt in range(1, n):
                    if mask & (1 << nxt):
                        continue
                    key = (mask | (1 << nxt), nxt)
                    cand = (length+dist[last][nxt], path+(nxt,))
                    if key not in dp or cand < dp[key]:
                        dp[key] = cand
        full = (1 << n)-1
        _, path = min((dp[(full, l)][0]+dist[l][0], dp[(full, l)][1]) for l in range(1, n))
        return [pts[i] for i in path]

    def edges_cells(pts):
        h = outline(pts)
        cells = []
        n = len(h)
        if n < 2:
            return cells
        pairs = [(h[0], h[1])] if n == 2 else [(h[i], h[(i+1) % n]) for i in range(n)]
        for (a, b) in pairs:
            dy, dx = b[0]-a[0], b[1]-a[1]
            if not (dy == 0 or dx == 0 or abs(dy) == abs(dx)):
                continue
            L = max(abs(dy), abs(dx))
            sy, sx = sign(dy), sign(dx)
            for k in range(L+1):
                cells.append((a[0]+k*sy, a[1]+k*sx))
        return cells

    colours = [int(c) for c in np.unique(g) if c != bg]
    cells_of = {c: [(int(p[0]), int(p[1])) for p in np.argwhere(g == c)] for c in colours}
    shapes = {c: edges_cells(cells_of[c]) for c in colours if len(cells_of[c]) >= 2}

    # 1. draw each colour's outline through its markers
    for c, cells in shapes.items():
        if not cells:
            continue
        for (y, x) in cells:
            out[y, x] = c
        emit(out.copy(), f"Draw the straight/diagonal edges of the polygon through all markers of colour {c}.")

    # 2. single companion pixel next to a shape -> shifted copy drawn underneath
    for c in colours:
        if len(cells_of[c]) != 1:
            continue
        (cy, cx) = cells_of[c][0]
        found = None
        for dy in (-1, 0, 1):
            for dx in (-1, 0, 1):
                if dy == 0 and dx == 0:
                    continue
                y, x = cy+dy, cx+dx
                if 0 <= y < H and 0 <= x < W:
                    v = int(g[y, x])
                    if v != bg and v != c and v in shapes:
                        found = (v, cy-y, cx-x)
        if found is None:
            continue
        v, oy, ox = found
        if not shapes[v]:
            continue
        for (y, x) in shapes[v]:
            ny, nx = y+oy, x+ox
            if 0 <= ny < H and 0 <= nx < W and out[ny, nx] == bg:
                out[ny, nx] = c
        emit(out.copy(), f"Colour {c} traces colour {v}'s outline shifted by ({oy},{ox}), underneath.")

    emit(out.copy(), "Final grid.")
    return out
